-- PT111-S3-Q7. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT111-S3-Q7$batch06$ AND q.stimulus=$batch06$Opponent of offshore oil drilling: The projected benefits of drilling new oil wells in certain areas in the outer continental shelf are not worth the risk of environmental disaster. The oil already being extracted from these areas currently provides only 4 percent of our country’s daily oil requirement, and the new wells would only add one-half of 1 percent.Proponent of offshore oil drilling: Don’t be ridiculous! You might just as well argue that new farms should not be allowed, since no new farm could supply the total food needs of our country for more than a few minutes.$batch06$ AND q.prompt=$batch06$The drilling proponent's reply to the drilling opponent proceeds by$batch06$ AND q.correct_choice=$batch06$D$batch06$) THEN RAISE EXCEPTION 'Question changed: PT111-S3-Q7'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT111-S3-Q7$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT111-S3-Q7'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT111-S3-Q7$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$(Proponent) The opponent's argument is ridiculous.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$By the same logic, new farms should not be allowed, since no single new farm could feed the country for more than a few minutes.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$The opponent says the new wells add too little to be worth it. The proponent does not dispute the 4 percent or the half of 1 percent. Instead, they copy the shape of the argument ("this adds only a tiny share, so it is not worth it") onto farms, where the conclusion is plainly silly. If the same reasoning gives an absurd answer elsewhere, something is wrong with it.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Citing a parallel argument whose conclusion is plainly unsupported.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT111-S3-Q7$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$The proponent offers no evidence for drilling at all. The reply is a parallel argument, not more data.$batch06$), ($batch06$B$batch06$, $batch06$The proponent never disputes the 4 percent or the half of 1 percent.$batch06$), ($batch06$C$batch06$, $batch06$This is the most popular wrong answer. It sounds sophisticated, but the proponent never says the opponent's way of arguing is usually legitimate. The farm example says it fails, full stop.$batch06$), ($batch06$D$batch06$, $batch06$The parallel argument is the farms. Its conclusion, that no new farms should be allowed, is strikingly unsupported, which shows the opponent's reasoning is just as weak.$batch06$), ($batch06$E$batch06$, $batch06$The proponent does not propose a better conclusion from the opponent's evidence.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT111-S3-Q7$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
